using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace ApiMcpServer;

[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("Retrieve a single resource by its numeric ID.")]
    public async Task<string> GetResource(
        [Description("The numeric ID of the resource to retrieve")] int id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching resource {Id}", id);
        var json = await httpClient.GetStringAsync($"/posts/{id}", cancellationToken);
        return json;
    }

    [McpServerTool, Description("List all resources, optionally filtered by user ID.")]
    public async Task<string> ListResources(
        [Description("Optional user ID to filter resources by author")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var url = userId.HasValue ? $"/posts?userId={userId}" : "/posts";
        logger.LogInformation("Listing resources from {Url}", url);
        var json = await httpClient.GetStringAsync(url, cancellationToken);

        // Return a summary to keep token usage manageable
        var items = JsonSerializer.Deserialize<JsonElement[]>(json);
        return $"Found {items?.Length ?? 0} resources:\n{json}";
    }

    [McpServerTool, Description("Create a new resource with a title and body.")]
    public async Task<string> CreateResource(
        [Description("Title for the new resource")] string title,
        [Description("Body content for the new resource")] string body,
        [Description("Author user ID")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating resource for user {UserId}", userId);
        var payload = new { title, body, userId };
        var response = await httpClient.PostAsJsonAsync("/posts", payload, cancellationToken);
        response.EnsureSuccessStatusCode();
        var result = await response.Content.ReadAsStringAsync(cancellationToken);
        return result;
    }
}

